#include "postquantiquecoin/wallet/WalletKey.h"
#include "postquantiquecoin/core/Serialization.h"
namespace pqc { std::vector<uint8_t> WalletKey::Serialize() const { Serializer s; s.U32(1); s.String(label); s.Bytes(publicKey); s.Bytes(encryptedPrivateKey); s.String(address); s.String(signatureAlgorithm); s.U64(createdTimestamp); return s.Data(); } Result<WalletKey> WalletKey::Deserialize(const std::vector<uint8_t>& data){ Deserializer d(data); WalletKey k; auto v=d.U32(); if(v.IsErr()||v.Value()!=1) return Result<WalletKey>::Err("bad wallet key version"); auto l=d.String(); if(l.IsErr()) return Result<WalletKey>::Err(l.Error()); k.label=l.Value(); auto p=d.Bytes(); if(p.IsErr()) return Result<WalletKey>::Err(p.Error()); k.publicKey=p.Value(); auto e=d.Bytes(); if(e.IsErr()) return Result<WalletKey>::Err(e.Error()); k.encryptedPrivateKey=e.Value(); auto a=d.String(); if(a.IsErr()) return Result<WalletKey>::Err(a.Error()); k.address=a.Value(); auto alg=d.String(); if(alg.IsErr()) return Result<WalletKey>::Err(alg.Error()); k.signatureAlgorithm=alg.Value(); auto ts=d.U64(); if(ts.IsErr()) return Result<WalletKey>::Err(ts.Error()); k.createdTimestamp=ts.Value(); return Result<WalletKey>::Ok(k); } }
